*/
scwin.openNonListingBond = async function (_std_cd, _bnd_appl_id, _bnd_list_procs_tp_cd) {
    /* sdd-asis-lifecycle:begin fn_openNonListingBond — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent("dma_openNewListingReq").set("stdCd", _std_cd);
    $c.util.getComponent("dma_openNewListingReq").set("bndApplId", _bnd_appl_id);
    $c.util.getComponent("dma_openNewListingReq").set("bndListProcsTpCd", _bnd_list_procs_tp_cd);
    if (_bnd_list_procs_tp_cd === '0') {
        $c.util.getComponent('dma_openNewListingReq').set('flag', "TEMP");
    } else {
        $c.util.getComponent('dma_openNewListingReq').set('flag', "CONV");
    }
    $c.util.getComponent('dma_openNewListingReq').set('method', 'eachListingView');
    frm.action = '/listeach/eachListing.do';
    frm.target = "_self";
    await scwin.tx_fn_openNonListingBond();
    /* sdd-asis-lifecycle:end */
};


